//! Golden-file parity against the Python oracle.
//!
//! Fixtures are generated by `scripts/parity_export.py` from the reference
//! implementation *before* it is deleted. The Rust core must reproduce them
//! byte for byte; a divergence is a build failure, not a warning.

use hragents_core::audit::{AuditActor, AuditEntry};
use hragents_core::hiring::{Dimension, Evaluation, Rubric, RunScores};
use hragents_core::ids::{ApplicationId, RateTableId};
use hragents_core::money::Money;
use hragents_core::payroll::{RateEntry, RateTable, RateTableKind, compute_pph21};
use hragents_core::time::BusinessDate;
use hragents_core::time::UtcInstant;
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct MoneyCase {
    name: String,
    input: String,
    sen: i64,
}

#[derive(Deserialize)]
struct MoneyOperation {
    name: String,
    amount: Option<String>,
    percent: Option<String>,
    left: Option<String>,
    right: Option<String>,
    sen: i64,
}

#[derive(Deserialize)]
struct AuditCase {
    name: String,
    actor: AuditActor,
    action: String,
    subject_type: String,
    subject_id: String,
    payload: Value,
    created_at: String,
    prev_hash: Option<String>,
    entry_hash: String,
}

fn percent_bp(value: &str) -> i64 {
    // Percent strings in the oracle are exact decimals with at most two places.
    let (whole, fraction) = value.split_once('.').unwrap_or((value, ""));
    let mut digits = fraction.to_owned();
    while digits.len() < 2 {
        digits.push('0');
    }
    let whole: i64 = whole.parse().expect("percent whole");
    let fraction: i64 = digits[..2].parse().expect("percent fraction");
    whole * 100 + fraction
}

#[test]
fn money_matches_python() {
    let cases: Vec<MoneyCase> =
        serde_json::from_str(include_str!("../../../../parity/fixtures/money.json")).unwrap();
    assert!(!cases.is_empty());
    for case in cases {
        let parsed = Money::parse(&case.input).unwrap();
        assert_eq!(
            parsed.sen(),
            case.sen,
            "money case {} ({}) diverged",
            case.name,
            case.input
        );
    }
}

#[test]
fn money_operations_match_python() {
    let operations: Vec<MoneyOperation> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/money_operations.json"
    ))
    .unwrap();
    assert!(!operations.is_empty());
    for operation in operations {
        let actual = match operation.name.as_str() {
            "percent_2_5" => Money::parse(operation.amount.as_deref().unwrap())
                .unwrap()
                .percent_bp(percent_bp(operation.percent.as_deref().unwrap()))
                .unwrap(),
            "add" => Money::parse(operation.left.as_deref().unwrap())
                .unwrap()
                .checked_add(Money::parse(operation.right.as_deref().unwrap()).unwrap())
                .unwrap(),
            "sub" => Money::parse(operation.left.as_deref().unwrap())
                .unwrap()
                .checked_sub(Money::parse(operation.right.as_deref().unwrap()).unwrap())
                .unwrap(),
            other => panic!("unknown money operation fixture {other}"),
        };
        assert_eq!(
            actual.sen(),
            operation.sen,
            "operation {} diverged",
            operation.name
        );
    }
}

#[test]
fn audit_hashes_match_python() {
    let cases: Vec<AuditCase> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/audit_hashes.json"
    ))
    .unwrap();
    assert_eq!(cases.len(), 2);
    for case in &cases {
        let created_at = UtcInstant::from_rfc3339(&case.created_at).unwrap();
        let actual = AuditEntry::compute_hash(
            case.prev_hash.as_deref(),
            &case.actor,
            &case.action,
            &case.subject_type,
            &case.subject_id,
            &case.payload,
            created_at,
        )
        .unwrap();
        assert_eq!(actual, case.entry_hash, "audit case {} diverged", case.name);
    }
    // The second fixture chains onto the first: verify the link, not just the hash.
    assert_eq!(
        cases[1].prev_hash.as_deref(),
        Some(cases[0].entry_hash.as_str())
    );
}

#[derive(Deserialize)]
struct Pph21Case {
    name: String,
    gross: String,
    exemption: String,
    sen: i64,
}

fn ter_table() -> RateTable {
    let bracket = |lower: i64, upper: i64, rate_bp: i64| RateEntry {
        key: None,
        employee_share_bp: rate_bp,
        employer_share_bp: 0,
        wage_cap: None,
        flat_amount: None,
        multiplier_bp: None,
        lower_bound: Some(Money::from_rupiah(lower).unwrap()),
        upper_bound: Some(Money::from_rupiah(upper).unwrap()),
        hours_per_month: None,
        note: None,
    };
    RateTable {
        id: RateTableId::new(),
        kind: RateTableKind::Pph21Ter,
        effective_from: BusinessDate::parse("2026-01-01").unwrap(),
        effective_to: None,
        verified: true,
        verified_by: Some("fixture".into()),
        verified_at: None,
        source_note: Some("parity fixture".into()),
        entries: vec![
            bracket(0, 10_000_000, 50),
            bracket(10_000_000, 100_000_000, 100),
            bracket(100_000_000, 1_000_000_000, 200),
        ],
    }
}

#[test]
fn pph21_progressive_matches_python() {
    let cases: Vec<Pph21Case> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/payroll_pph21.json"
    ))
    .unwrap();
    assert!(!cases.is_empty());
    let table = ter_table();
    for case in cases {
        let tax = compute_pph21(
            &table,
            Money::parse(&case.gross).unwrap(),
            Money::parse(&case.exemption).unwrap(),
        )
        .unwrap();
        assert_eq!(tax.sen(), case.sen, "PPh 21 case {} diverged", case.name);
    }
}

#[derive(Deserialize)]
struct ScoringCase {
    weights_bp: std::collections::BTreeMap<String, i64>,
    runs: Vec<std::collections::BTreeMap<String, i64>>,
    dimension_scores_bp: std::collections::BTreeMap<String, i64>,
    overall_bp: i64,
    sigma_bp: i64,
}

#[derive(Deserialize)]
struct ScoringDimensionCase {
    name: String,
    weights_bp: std::collections::BTreeMap<String, i64>,
    sigma_limit_bp: i64,
    runs: Vec<std::collections::BTreeMap<String, i64>>,
    dimension_scores_bp: std::collections::BTreeMap<String, i64>,
    overall_bp: i64,
    sigma_bp: i64,
    inconsistent: bool,
}

#[test]
fn scoring_dimensions_match_python() {
    let cases: Vec<ScoringDimensionCase> = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/scoring_dimensions.json"
    ))
    .unwrap();
    assert_eq!(cases.len(), 11);
    for case in &cases {
        let rubric = Rubric {
            id: "score-vector-v1".into(),
            name: "Score vector parity".into(),
            dimensions: case
                .weights_bp
                .iter()
                .map(|(key, weight_bp)| Dimension {
                    key: key.clone(),
                    label: key.clone(),
                    weight_bp: *weight_bp,
                })
                .collect(),
            merit_floor_bp: 7_000,
            sigma_limit_bp: case.sigma_limit_bp,
        };
        let runs: Vec<RunScores> = case
            .runs
            .iter()
            .map(|scores| RunScores {
                dimension_scores: scores.clone(),
            })
            .collect();
        let evaluation = Evaluation::from_runs(
            ApplicationId::new(),
            &rubric,
            &runs,
            Vec::new(),
            UtcInstant::from_millis(1_760_000_000_000).unwrap(),
        )
        .unwrap();
        assert_eq!(
            evaluation.dimension_scores, case.dimension_scores_bp,
            "case {}: dimension means diverged",
            case.name
        );
        assert_eq!(
            evaluation.overall_bp, case.overall_bp,
            "case {}: overall diverged",
            case.name
        );
        assert_eq!(
            evaluation.sigma_bp, case.sigma_bp,
            "case {}: sigma diverged",
            case.name
        );
        assert_eq!(
            evaluation
                .flags
                .iter()
                .any(|flag| flag == "inconsistent_extraction"),
            case.inconsistent,
            "case {}: inconsistency flag diverged",
            case.name
        );
    }
}

#[test]
fn scoring_aggregate_matches_python() {
    let case: ScoringCase = serde_json::from_str(include_str!(
        "../../../../parity/fixtures/scoring_aggregate.json"
    ))
    .unwrap();
    let rubric = Rubric {
        id: "score-vector-v1".into(),
        name: "Score vector parity".into(),
        dimensions: case
            .weights_bp
            .iter()
            .map(|(key, weight_bp)| Dimension {
                key: key.clone(),
                label: key.clone(),
                weight_bp: *weight_bp,
            })
            .collect(),
        merit_floor_bp: 7_000,
        sigma_limit_bp: 500,
    };
    let runs: Vec<RunScores> = case
        .runs
        .iter()
        .map(|scores| RunScores {
            dimension_scores: scores.clone(),
        })
        .collect();
    let evaluation = Evaluation::from_runs(
        ApplicationId::new(),
        &rubric,
        &runs,
        Vec::new(),
        UtcInstant::from_millis(1_760_000_000_000).unwrap(),
    )
    .unwrap();
    assert_eq!(evaluation.dimension_scores, case.dimension_scores_bp);
    assert_eq!(evaluation.overall_bp, case.overall_bp);
    assert_eq!(evaluation.sigma_bp, case.sigma_bp);
}
